//! Shell integration — open URLs, files, and reveal-in-folder.
//!
//! Dispatch is generated by `#[tynd::handler]` (U10) — typed per-arg
//! deser collapses the manual `args.get("...")` chain.

use crate::{ipc_error::IpcError, tynd};

/// Marker for the `#[tynd::handler]` dispatch table — shell is
/// stateless; every method is associated.
#[derive(Debug, Default)]
pub struct ShellApi;

#[tynd::handler(api = "shell")]
impl ShellApi {
    /// Open `url` in the user's default browser. Only `http`, `https`,
    /// and `mailto` schemes are accepted — anything else is rejected so
    /// a frontend bug or XSS can't pivot through `shell.openExternal`
    /// to invoke a custom protocol handler.
    pub fn open_external(url: String) -> Result<(), String> {
        if !url.starts_with("http://")
            && !url.starts_with("https://")
            && !url.starts_with("mailto:")
        {
            return Err(IpcError::new(
                "shell",
                "openExternal",
                format!("unsupported scheme in '{url}' — only http, https, mailto allowed"),
            )
            .into_string());
        }
        open::that(&url).map_err(|e| e.to_string())?;
        Ok(())
    }

    /// Open `path` with the OS's default handler. On Windows we refuse
    /// known executable extensions so that a frontend bug or XSS can't
    /// turn `shell.openPath` into a remote-code-execution primitive —
    /// callers that need to launch a binary should use `process.exec`
    /// instead (which goes through capability checks).
    pub fn open_path(path: String) -> Result<(), String> {
        // Stored as a `phf::Set` so the lookup is a single perfect hash
        // + slot comparison at runtime (built at `cargo build` time)
        // instead of an O(N) `iter().any(...)`. All entries are
        // lowercase; the input is folded to lowercase before the
        // lookup to keep the previous case-insensitive contract.
        static EXEC_EXTS: phf::Set<&'static str> = phf::phf_set! {
            "exe", "bat", "cmd", "ps1", "psm1", "msi", "msp", "scr", "vbs", "vbe", "wsf",
            "wsh", "com", "pif", "cpl", "jar",
        };
        if let Some(ext) = std::path::Path::new(&path)
            .extension()
            .and_then(|e| e.to_str())
        {
            if EXEC_EXTS.contains(ext.to_ascii_lowercase().as_str()) {
                return Err(IpcError::new(
                    "shell",
                    "openPath",
                    format!(
                        "refusing to open executable '{path}' — use process.exec for binaries"
                    ),
                )
                .into_string());
            }
        }
        open::that(&path).map_err(|e| e.to_string())?;
        Ok(())
    }

    /// Open the OS file manager with `path` selected/highlighted.
    /// Uses the native "reveal" gesture (Explorer `/select`, Finder
    /// `open -R`, `xdg-open` parent on Linux) so the user sees the
    /// item in-place.
    pub fn reveal_in_folder(path: String) -> Result<(), String> {
        reveal(&path)
    }
}

/// Open the OS file manager with `path` selected / highlighted. Uses the
/// native "reveal" gesture (explorer /select, Finder open -R, xdg-open
/// parent) so the user sees the item in-place.
#[cfg(target_os = "windows")]
fn reveal(path: &str) -> Result<(), String> {
    let p = std::path::Path::new(path);
    if !p.exists() {
        return Err(IpcError::new(
            "shell",
            "revealInFolder",
            format!("({path}): path does not exist"),
        )
        .into_string());
    }
    std::process::Command::new("explorer")
        .arg(format!("/select,{}", p.display()))
        .spawn()
        .map_err(|e| IpcError::new("shell", "revealInFolder", e).into_string())?;
    Ok(())
}

#[cfg(target_os = "macos")]
fn reveal(path: &str) -> Result<(), String> {
    if !std::path::Path::new(path).exists() {
        return Err(IpcError::new(
            "shell",
            "revealInFolder",
            format!("({path}): path does not exist"),
        )
        .into_string());
    }
    std::process::Command::new("open")
        .args(["-R", path])
        .spawn()
        .map_err(|e| IpcError::new("shell", "revealInFolder", e).into_string())?;
    Ok(())
}

#[cfg(all(unix, not(target_os = "macos")))]
fn reveal(path: &str) -> Result<(), String> {
    let p = std::path::Path::new(path);
    if !p.exists() {
        return Err(IpcError::new(
            "shell",
            "revealInFolder",
            format!("({path}): path does not exist"),
        )
        .into_string());
    }
    // No single Linux convention — open the parent dir, works on every
    // desktop that has `xdg-open` installed.
    let parent = p.parent().unwrap_or(p);
    open::that(parent).map_err(|e| IpcError::new("shell", "revealInFolder", e).into_string())?;
    Ok(())
}

#[cfg(test)]
mod tests {
    use serde_json::json;

    use super::*;

    #[test]
    fn rejects_unsupported_scheme() {
        for bad in [
            "file:///etc/passwd",
            "javascript:alert(1)",
            "ftp://example.com",
            "vscode://open?file=x",
            "data:text/html,<script>",
            "no-scheme-at-all",
        ] {
            let err = dispatch("openExternal", &json!({ "url": bad })).expect_err(bad);
            assert!(err.contains("unsupported scheme"), "{bad}: {err}");
        }
    }

    #[test]
    fn missing_url_is_reported() {
        let err = dispatch("openExternal", &json!({})).unwrap_err();
        assert!(err.contains("missing 'url'"));
    }

    #[test]
    fn missing_path_is_reported() {
        let err = dispatch("openPath", &json!({})).unwrap_err();
        assert!(err.contains("missing 'path'"));
    }

    #[test]
    fn unknown_method_errors() {
        assert!(dispatch("nope", &json!({})).is_err());
    }

    #[test]
    fn accepts_url_from_object_form() {
        let err = dispatch("openExternal", &json!({ "url": "ftp://x" })).unwrap_err();
        assert!(err.contains("unsupported scheme"));
    }
}
